import { Controller, Get, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const COMPONENT_TYPES = ['WIDGET', 'BANNER', 'MENU'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr02604Controller {
  @Get('/portal-personalizations')
  async listPortalPersonalizations(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    let size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 건수 형식이 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT portal_personalization_id AS "portalPersonalizationId",
                component_type AS "componentType",
                component_key AS "componentKey",
                visible_yn AS "visibleYn",
                sort_order AS "sortOrder"
           FROM portal_personalization
          WHERE employee_id = CAST(:userId AS bigint)
          ORDER BY sort_order ASC NULLS LAST, portal_personalization_id ASC
          LIMIT :size OFFSET :offset`,
        { userId: user.id, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM portal_personalization
          WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Put('/portal-personalizations')
  async savePortalPersonalization(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const componentType = data['componentType'];
    const componentKey = data['componentKey'];
    const visibleYn = data['visibleYn'];
    const sortOrder = data['sortOrder'];
    if (typeof componentType !== 'string' || !COMPONENT_TYPES.includes(componentType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '구성 유형은 WIDGET, BANNER, MENU 중 하나여야 합니다.');
    }
    if (typeof componentKey !== 'string' || componentKey.trim() === '' || componentKey.length > 100) {
      throw new ApiError(400, 'VALIDATION_FAILED', '구성 식별값은 100자 이하로 입력해야 합니다.');
    }
    if (typeof visibleYn !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '표시 여부는 true 또는 false여야 합니다.');
    }
    let order: number | null = null;
    if (sortOrder !== undefined && sortOrder !== null && sortOrder !== '') {
      if (typeof sortOrder !== 'number' || !Number.isInteger(sortOrder) || sortOrder < 0 || sortOrder > 2147483647) {
        throw new ApiError(400, 'VALIDATION_FAILED', '배치 순서는 0 이상의 정수여야 합니다.');
      }
      order = sortOrder;
    }
    const key = componentKey.trim();
    const isMenu = componentType === 'MENU';
    // 가정: 메뉴(MENU)는 구성 식별값에 menu_id 숫자를 넣어 보낸다.
    if (isMenu && !/^\d{1,18}$/.test(key)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '메뉴 구성 식별값은 메뉴 ID 숫자여야 합니다.');
    }
    return transaction(async (db) => {
      if (isMenu) {
        const menus = await db.query(
          'SELECT menu_id FROM menu WHERE menu_id = CAST(:key AS bigint)',
          { key },
        );
        if (menus.length === 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '존재하지 않는 메뉴입니다.');
        }
      }
      const found = isMenu
        ? await db.query(
          `SELECT portal_personalization_id AS "id"
             FROM portal_personalization
            WHERE employee_id = CAST(:userId AS bigint)
              AND menu_id = CAST(:key AS bigint)`,
          { userId: user.id, key },
        )
        : await db.query(
          `SELECT portal_personalization_id AS "id"
             FROM portal_personalization
            WHERE employee_id = CAST(:userId AS bigint)
              AND component_type = :componentType
              AND component_key = :key`,
          { userId: user.id, componentType, key },
        );
      if (found.length > 0) {
        const rows = await db.query(
          `UPDATE portal_personalization
              SET visible_yn = :visibleYn,
                  sort_order = COALESCE(CAST(:sortOrder AS integer), sort_order),
                  updated_at = now()
            WHERE portal_personalization_id = CAST(:id AS bigint)
              AND employee_id = CAST(:userId AS bigint)
        RETURNING portal_personalization_id AS "portalPersonalizationId"`,
          { visibleYn, sortOrder: order, id: String(found[0]['id']), userId: user.id },
        );
        return rows[0];
      }
      const rows = await db.query(
        `INSERT INTO portal_personalization
                (employee_id, menu_id, component_type, component_key, visible_yn, sort_order, created_at, updated_at)
         VALUES (CAST(:userId AS bigint),
                 CASE WHEN :componentType = 'MENU' THEN CAST(:key AS bigint) ELSE NULL END,
                 :componentType, :key, :visibleYn, CAST(:sortOrder AS integer), now(), now())
      RETURNING portal_personalization_id AS "portalPersonalizationId"`,
        { userId: user.id, componentType, key, visibleYn, sortOrder: order },
      );
      return rows[0];
    });
  }
}

