import { useState } from 'react';
import {
  call, useData, Badge, Num, Band, DataTable, Pager, Drawer, Tiles, Form, Field,
  TextInput, NumberInput, Select, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;
const TYPE_OPTIONS: [string, string][] = [
  ['WIDGET', '위젯'],
  ['BANNER', '배너'],
  ['MENU', '메뉴'],
];
const TYPE_NAMES: Record<string, string> = { WIDGET: '위젯', BANNER: '배너', MENU: '메뉴' };

export default function FnSfr02604Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [open, setOpen] = useState(false);
  const [componentType, setComponentType] = useState('WIDGET');
  const [componentKey, setComponentKey] = useState('');
  const [visibleYn, setVisibleYn] = useState('true');
  const [sortOrder, setSortOrder] = useState<number | string>('');
  const [actionError, setActionError] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/portal-personalizations', role, undefined, { page, size: SIZE }),
    [role, page],
  );
  const rows = data ? data.items : [];
  const shown = rows.filter((r) => r['visibleYn'] === true).length;

  function openNew() {
    setComponentType('WIDGET');
    setComponentKey('');
    setVisibleYn('true');
    setSortOrder('');
    setOpen(true);
  }

  function openEdit(row: Row) {
    setComponentType(String(row['componentType']));
    setComponentKey(String(row['componentKey'] ?? ''));
    setVisibleYn(row['visibleYn'] === true ? 'true' : 'false');
    setSortOrder(row['sortOrder'] === null || row['sortOrder'] === undefined ? '' : Number(row['sortOrder']));
    setOpen(true);
  }

  async function toggle(row: Row) {
    setActionError('');
    try {
      const body: Row = {
        componentType: row['componentType'],
        componentKey: row['componentKey'],
        visibleYn: row['visibleYn'] !== true,
      };
      if (row['sortOrder'] !== null && row['sortOrder'] !== undefined) {
        body['sortOrder'] = row['sortOrder'];
      }
      await call('PUT', '/portal-personalizations', role, body);
      notify('개인화 설정을 저장했습니다.');
      reload();
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '저장하지 못했습니다.');
    }
  }

  async function save() {
    if (!componentKey.trim()) {
      throw new Error('구성 식별값을 입력하세요.');
    }
    if (sortOrder !== '' && (typeof sortOrder !== 'number' || sortOrder < 0)) {
      throw new Error('배치 순서는 0 이상의 숫자로 입력하세요.');
    }
    const body: Row = {
      componentType,
      componentKey: componentKey.trim(),
      visibleYn: visibleYn === 'true',
    };
    if (sortOrder !== '') {
      body['sortOrder'] = sortOrder;
    }
    await call('PUT', '/portal-personalizations', role, body);
    notify('개인화 설정을 저장했습니다.');
    setOpen(false);
    reload();
  }

  const columns: Column[] = [
    {
      key: 'componentType',
      label: '구성 유형',
      render: (r) => <span>{TYPE_NAMES[String(r['componentType'])] ?? String(r['componentType'])}</span>,
    },
    {
      key: 'componentKey',
      label: '구성 식별값',
      render: (r) => (r['componentType'] === 'MENU'
        ? <RefName table="menu" role={role} value={Number(r['componentKey'])} />
        : <span>{String(r['componentKey'] ?? '')}</span>),
    },
    {
      key: 'visibleYn',
      label: '표시 여부',
      render: (r) => <Badge value={r['visibleYn'] === true ? '표시' : '숨김'} />,
    },
    {
      key: 'sortOrder',
      label: '배치 순서',
      render: (r) => <Num value={r['sortOrder']} />,
    },
    {
      key: 'actions',
      label: '처리',
      render: (r) => (
        <span>
          <button type="button" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
          {' '}
          <button type="button" onClick={(e) => { e.stopPropagation(); toggle(r); }}>
            {r['visibleYn'] === true ? '숨기기' : '표시하기'}
          </button>
        </span>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>내 포털 현황</h2>
        <Tiles
          items={[
            ['전체 구성', <Num value={data ? data.total : 0} />],
            ['표시 중 (현재 쪽)', <Num value={shown} />],
            ['숨김 (현재 쪽)', <Num value={rows.length - shown} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>위젯·배너 구성</h2>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openNew}>구성 추가·변경</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        {actionError ? <ErrorText text={actionError} /> : null}
        <DataTable columns={columns} rows={rows} onRowClick={openEdit} empty="저장된 개인화 설정이 없습니다." />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {open ? (
        <Drawer title="포털 개인화 저장" onClose={() => setOpen(false)}>
          <Form onSubmit={save} submit="저장">
            <Field label="구성 유형" required>
              <Select value={componentType} onChange={setComponentType} options={TYPE_OPTIONS} />
            </Field>
            <Field label="구성 식별값" required hint="메뉴는 메뉴 ID 숫자를 입력합니다.">
              <TextInput value={componentKey} onChange={setComponentKey} />
            </Field>
            <Field label="표시 여부" required>
              <Select
                value={visibleYn}
                onChange={setVisibleYn}
                options={[['true', '표시'], ['false', '숨김']]}
              />
            </Field>
            <Field label="배치 순서">
              <NumberInput value={sortOrder} onChange={setSortOrder} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
